-- Planificación completa de plazas liberadas y procesos de reclutamiento.
alter table public.hr_vacancies drop constraint if exists hr_vacancies_status_check;
alter table public.hr_vacancies add constraint hr_vacancies_status_check check(status in('VACANTE','CON_RECLUTAMIENTO','CONGELADA','ELIMINADA','OCUPADA','CANCELADA'));
alter table public.hr_vacancies add column if not exists decision text not null default 'PENDIENTE' check(decision in('PENDIENTE','CUBRIR','CONGELAR','ELIMINAR'));
alter table public.hr_vacancies add column if not exists decision_reason text not null default '';
alter table public.hr_vacancies add column if not exists decision_by uuid references public.app_users(id);
alter table public.hr_vacancies add column if not exists decision_at timestamptz;

create table if not exists public.hr_recruitment_processes(
 id uuid primary key default gen_random_uuid(),vacancy_id uuid not null references public.hr_vacancies(id),process_number bigint generated always as identity,
 status text not null default 'INICIADO' check(status in('INICIADO','PUBLICADO','EVALUACION','SELECCIONADO','CERRADO','CANCELADO')),
 start_date date not null default current_date,reference text not null default '',notes text not null default '',selected_employee_id uuid references public.hr_employees(id),
 created_by uuid not null references public.app_users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now()
);
create unique index if not exists hr_recruitment_active_vacancy_idx on public.hr_recruitment_processes(vacancy_id) where status not in('CERRADO','CANCELADO');
alter table public.hr_recruitment_processes enable row level security;revoke all on public.hr_recruitment_processes from anon,authenticated;

create or replace function public.list_hr_vacancy_planning(p_token text,p_year integer,p_month integer)
returns jsonb language plpgsql security definer set search_path=public,extensions as $$declare v_user public.app_users;v_end date:=(make_date(p_year,p_month,1)+interval '1 month - 1 day')::date;begin v_user:=public.hr_authenticated_user(p_token);
 if v_user.id is null or (v_user.role<>'Administrador' and not coalesce((v_user.permissions->>'ver_recursos_humanos')::boolean,false)) then return jsonb_build_object('success',false,'error','No posee permiso para consultar la planificación de vacantes.');end if;
 return jsonb_build_object('success',true,'period_end',v_end,
 'items',coalesce((select jsonb_agg(to_jsonb(x) order by x.direction_name,x.department_name,x.position_name) from(select v.*,e.full_name filled_employee_name,r.id recruitment_id,r.process_number,r.status recruitment_status,r.start_date recruitment_start,r.reference recruitment_reference from public.hr_vacancies v left join public.hr_employees e on e.id=v.filled_by_employee_id left join lateral(select * from public.hr_recruitment_processes r where r.vacancy_id=v.id order by r.created_at desc limit 1)r on true where v.available_from<=v_end)x),'[]'::jsonb),
 'areas',coalesce((select jsonb_agg(to_jsonb(a) order by a.monthly_available desc,a.direction_name,a.department_name) from(select direction_name,department_name,count(*) filter(where status in('VACANTE','CON_RECLUTAMIENTO'))::integer vacancy_count,sum(monthly_amount) filter(where status in('VACANTE','CON_RECLUTAMIENTO'))::numeric(18,2) monthly_available,sum(monthly_amount*greatest(0,13-greatest(p_month,extract(month from available_from)::integer))) filter(where status in('VACANTE','CON_RECLUTAMIENTO'))::numeric(18,2) annual_available from public.hr_vacancies where available_from<=v_end group by direction_name,department_name)a),'[]'::jsonb),
 'employees',coalesce((select jsonb_agg(jsonb_build_object('id',e.id,'employee_code',e.employee_code,'full_name',e.full_name,'position_name',e.position_name,'direction_name',e.direction_name,'department_name',e.department_name) order by e.full_name) from public.hr_employees e where e.employment_status<>'Desvinculado'),'[]'::jsonb));end $$;

create or replace function public.manage_hr_vacancy(p_token text,p_vacancy_id uuid,p_action text,p_data jsonb)
returns jsonb language plpgsql security definer set search_path=public,extensions as $$declare v_user public.app_users;v_vacancy public.hr_vacancies;v_employee public.hr_employees;v_process uuid;v_decision text;begin v_user:=public.hr_authenticated_user(p_token);select * into v_vacancy from public.hr_vacancies where id=p_vacancy_id for update;
 if v_user.id is null or v_vacancy.id is null or (v_user.role<>'Administrador' and not coalesce((v_user.permissions->>'editar_recursos_humanos')::boolean,false)) then return jsonb_build_object('success',false,'error','No posee permiso para gestionar esta vacante.');end if;
 if p_action='DECISION' then v_decision:=upper(coalesce(p_data->>'decision',''));if v_decision not in('CUBRIR','CONGELAR','ELIMINAR') then return jsonb_build_object('success',false,'error','Decisión inválida.');end if;update public.hr_vacancies set decision=v_decision,decision_reason=trim(coalesce(p_data->>'reason','')),decision_by=v_user.id,decision_at=now(),status=case v_decision when 'CONGELAR' then 'CONGELADA' when 'ELIMINAR' then 'ELIMINADA' else 'VACANTE' end,updated_at=now() where id=p_vacancy_id;
 elsif p_action='RECLUTAR' then if v_vacancy.status not in('VACANTE','CON_RECLUTAMIENTO') or v_vacancy.decision<>'CUBRIR' then return jsonb_build_object('success',false,'error','Primero indique que la plaza será cubierta.');end if;insert into public.hr_recruitment_processes(vacancy_id,reference,notes,created_by) values(p_vacancy_id,trim(coalesce(p_data->>'reference','')),trim(coalesce(p_data->>'notes','')),v_user.id) on conflict(vacancy_id) where status not in('CERRADO','CANCELADO') do update set reference=excluded.reference,notes=excluded.notes,updated_at=now() returning id into v_process;update public.hr_vacancies set status='CON_RECLUTAMIENTO',updated_at=now() where id=p_vacancy_id;
 elsif p_action='VINCULAR' then select * into v_employee from public.hr_employees where id=(p_data->>'employee_id')::uuid and employment_status<>'Desvinculado' for update;if v_employee.id is null then return jsonb_build_object('success',false,'error','Seleccione un empleado activo válido.');end if;if v_vacancy.status not in('VACANTE','CON_RECLUTAMIENTO') or v_vacancy.decision<>'CUBRIR' then return jsonb_build_object('success',false,'error','La plaza no está disponible para vinculación.');end if;
  update public.hr_employees set position_name=v_vacancy.position_name,direction_name=v_vacancy.direction_name,department_name=v_vacancy.department_name,division_name=v_vacancy.division_name,section_name=v_vacancy.section_name,center_name=v_vacancy.center_name,execution_fund=v_vacancy.execution_fund,program=v_vacancy.program,subproduct=v_vacancy.subproduct,activity=v_vacancy.activity,monthly_salary=v_vacancy.monthly_amount,updated_at=now() where id=v_employee.id;
  update public.hr_vacancies set status='OCUPADA',filled_by_employee_id=v_employee.id,filled_at=now(),updated_at=now() where id=p_vacancy_id;update public.hr_recruitment_processes set status='CERRADO',selected_employee_id=v_employee.id,updated_at=now() where vacancy_id=p_vacancy_id and status not in('CERRADO','CANCELADO');
 else return jsonb_build_object('success',false,'error','Acción de vacante inválida.');end if;
 insert into public.security_audit_log(actor_user_id,action,module,detail) values(v_user.id,'GESTIONAR_VACANTE','Recursos Humanos',jsonb_build_object('vacancy_id',p_vacancy_id,'action',p_action,'data',p_data,'previous_status',v_vacancy.status));return jsonb_build_object('success',true,'recruitment_id',v_process);end $$;
grant execute on function public.list_hr_vacancy_planning(text,integer,integer),public.manage_hr_vacancy(text,uuid,text,jsonb) to anon,authenticated;
